-- 1. Enable trigram extension
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 2. GIN Trigram index for ultra-fast LIKE '%term%' searches
CREATE INDEX idx_products_name_trgm ON products USING gin (name gin_trgm_ops);

-- 3. Fuzzy search with similarity score (handles typos!)
SELECT name, similarity(name, 'postgress') AS match_score
FROM products
WHERE name % 'postgress' -- % operator: similarity threshold
ORDER BY match_score DESC
LIMIT 5;
